// Rewrites the data section of pinch.js from the lead animator's sources, so the engine never drifts from the art.
//   node docs/design/pinch/build.mjs
// Sources (all generated by build_pinch.py, except rig.js): pinch.svg, pinch-lod24.svg, pinch-lod20.svg, pinch-lod16.svg,
// rig.json, clips.json, and rig.js (the param -> transform mapping), embedded verbatim but bound to a local instead of window.
// Fails if the result could not be concatenated into a classic-script bundle.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const here = dirname(fileURLToPath(import.meta.url));
const read = (f) => readFileSync(join(here, f), 'utf8');
const BEGIN = '/* @pinch-data:begin */';
const END = '/* @pinch-data:end */';

const svg = { full: read('pinch.svg'), lod24: read('pinch-lod24.svg'), lod20: read('pinch-lod20.svg'), lod16: read('pinch-lod16.svg') };
const rig = JSON.parse(read('rig.json'));
const clips = JSON.parse(read('clips.json'));

const INVOKE = "})(typeof window !== 'undefined' ? window : globalThis);";
let rigSrc = read('rig.js').trim().replace(/^\/\*[\s\S]*?\*\/\s*/, ''); // its API comment lives in rig.js
if (!rigSrc.endsWith(INVOKE)) throw new Error('build.mjs: rig.js no longer ends with the expected IIFE call; update INVOKE');
rigSrc = rigSrc.slice(0, -INVOKE.length) + '})(LIB);';

const indent = (s) => s.split('\n').map((l) => (l ? '  ' + l : l)).join('\n');
const block = [
  BEGIN,
  '  /* Generated by build.mjs from pinch.svg, pinch-lod24/20/16.svg, rig.json, clips.json and rig.js. Do not edit by hand. */',
  '  var SVG = ' + JSON.stringify(svg) + ';',
  '  var RIG = ' + JSON.stringify(rig) + ';',
  '  var CLIPS = ' + JSON.stringify(clips) + ';',
  '  var LIB = {};',
  indent(rigSrc),
  '  ' + END,
].join('\n');

const target = join(here, 'pinch.js');
const src = read('pinch.js');
const a = src.indexOf(BEGIN), b = src.indexOf(END);
if (a < 0 || b < a) throw new Error('build.mjs: data markers not found in pinch.js');
const out = src.slice(0, a) + block + src.slice(b + END.length);

const problems = [];
if (/<\/script/i.test(out)) problems.push('"</script"');
if (out.includes('<!--')) problems.push('"<!--"');
if (/^\s*(import|export)\s/m.test(out)) problems.push('an import/export statement');
if (problems.length) throw new Error('build.mjs: pinch.js would not inline: ' + problems.join(', '));

writeFileSync(target, out);
execFileSync(process.execPath, ['--check', target], { stdio: 'inherit' });
const lines = out.split('\n').length;
console.log(`build.mjs: wrote pinch.js (${out.length} bytes, ${lines} lines; ${Object.keys(clips.moods).length} moods, ${Object.keys(clips.clips).length} clips)`);
